'use strict';
/**
 * send_linkedin_voice_note — sends a voice note generated by the brain (OpenVoice).
 * payload: { profile_url, audio_url, caption?, duration_sec?, prospect_id? }
 * The mp3 is downloaded to a temp file, passed to the recipe as {{file_path}}
 * (used by an `upload_file` step), and deleted afterwards.
 */
const fs = require('fs');
const os = require('os');
const path = require('path');
const crypto = require('crypto');
const { makeActionJob } = require('./_send');
const { JobError } = require('./_helpers');

const MAX_BYTES = 10 * 1024 * 1024;

const base = makeActionJob({
  type: 'send_linkedin_voice_note',
  platform: 'linkedin',
  required: ['profile_url', 'audio_url'],
  // Seeded recipe uses {{audio_path}} (+ optional {{caption}}); {{file_path}} kept as alias.
  vars: (p, ctx) => ({ profile_url: p.profile_url, file_path: ctx.tempAudioPath, audio_path: ctx.tempAudioPath, caption: p.caption || '' }),
  result: (p) => ({ voice_note: true, recipient: p.profile_url, duration_sec: p.duration_sec || null, prospect_id: p.prospect_id || null }),
});

module.exports = {
  ...base,
  async run(ctx) {
    const url = ctx.payload && ctx.payload.audio_url;
    if (!url) throw new JobError('missing_payload_fields:audio_url');
    const tmp = path.join(os.tmpdir(), `koneqti-voice-${crypto.randomBytes(6).toString('hex')}.mp3`);
    try {
      const res = await ctx.download(url);
      if (!res.ok) throw new JobError(`audio_download_http_${res.status}`);
      const buf = Buffer.from(await res.arrayBuffer());
      if (!buf.length || buf.length > MAX_BYTES) throw new JobError('audio_invalid_size');
      await fs.promises.writeFile(tmp, buf);
      ctx.tempAudioPath = tmp;
      return await base.run(ctx);
    } finally {
      fs.promises.rm(tmp, { force: true }).catch(() => {});
    }
  },
};
